import pandas as pd
import numpy as np

def clean(df):
    df = df.copy()
    if 'Price' in df.columns:
        df['Price'] = (df['Price'].astype(str)
                       .str.replace(r'[\$,]', '', regex=True)
                       .str.strip())
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
        df['Quantity'] = df['Quantity'].abs()
    if 'Region' in df.columns:
        df['Region'] = df['Region'].astype(str).str.strip()
        df['Region'] = df['Region'].replace({'Wst': 'West', 'Eats': 'East'})
        df.loc[df['Region'].isin(['nan', 'None', '']), 'Region'] = np.nan
    if 'Date' in df.columns:
        df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    if {'Quantity', 'Price', 'Revenue'}.issubset(df.columns):
        df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Category', 'Price'])
    result = d.groupby('Category')['Price'].mean().to_dict()
    return {str(k): float(v) for k, v in result.items()}
